package detect

import (
	"os"
	"testing"

	"github.com/praneeth132006/KrnlSentry/events"
)

// TestReplayGoldenCapture runs the full engine over a recorded capture and
// pins the result. It is the closest thing to an end-to-end test that runs
// without a kernel: the capture is the --verbose format the live agent writes,
// read back through the same events.ReadRecords path --replay uses.
//
// The capture (testdata/captures/intrusion.jsonl, generated by
// internal/gencapture) contains an SSH session in which four sibling processes
// steal cloud credentials, ptrace the login shell, call setuid(0) and open a
// reverse shell, interleaved with ordinary activity and a cron job that reads
// /etc/shadow in a loop.
func TestReplayGoldenCapture(t *testing.T) {
	f, err := os.Open("../testdata/captures/intrusion.jsonl")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()

	e := storyEngine(t, func(c *Config) { c.DedupWindow = DefaultConfig().DedupWindow })

	var alerts []*Alert
	n := 0
	err = events.ReadRecords(f, func(ev events.Event) error {
		n++
		alerts = append(alerts, e.Evaluate(ev)...)
		return nil
	})
	if err != nil {
		t.Fatalf("reading capture: %v", err)
	}
	if n != 38 {
		t.Fatalf("read %d events, want 38", n)
	}

	want := map[string]int{
		RuleNameSensitiveFile:       2, // cron backup (12 opens folded to 1) + aws creds
		RuleNameProcessInjection:    1,
		RuleNamePrivilegeEscalation: 1,
		RuleNameReverseShell:        1,
		RuleNameAttackChain:         2, // at 3 tactics, re-raised at 5
	}
	got := map[string]int{}
	for _, a := range alerts {
		got[a.Rule]++
	}
	for rule, w := range want {
		if got[rule] != w {
			t.Errorf("%s: got %d alerts, want %d", rule, got[rule], w)
		}
	}
	if len(alerts) != 7 {
		t.Errorf("got %d alerts total, want 7: %v", len(alerts), ruleNames(alerts))
	}

	if s := e.Stats().Suppressed; s != 11 {
		t.Errorf("folded %d duplicate alerts, want 11", s)
	}

	final := byRule(alerts, RuleNameAttackChain)[1]
	if final.Args["root"] != "bash[4100]" {
		t.Errorf("chain root = %s, want bash[4100]", final.Args["root"])
	}
	if final.Args["tactic_ids"] != "TA0006,TA0005,TA0004,TA0002,TA0011" {
		t.Errorf("chain tactic ids = %s", final.Args["tactic_ids"])
	}

	// The cron job is a different session and must not be in the story.
	backup := byRule(alerts, RuleNameSensitiveFile)[0]
	if backup.Comm != "backup.sh" {
		t.Fatalf("first sensitive-file alert is from %s, want backup.sh", backup.Comm)
	}
	if backup.Storyline == final.Storyline {
		t.Error("the cron backup was merged into the SSH intrusion's storyline")
	}
}
